"""Orbit of the optimal violated set of W(5,2) under Sp(6,2) (generated by the 63 symplectic transvections).
Compare with the Hoggar-SIC count: ASY-4 gives a bijection {optimal assignments} <-> {Pauli-covariant SIC fiducial
projectors in C^8}, and violated sets <-> SICs (fiducials modulo Pauli conjugation = gauge)."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'certificates'))
import certify as C
N = 3
pts, L, S = C.geometry('W', N)
toint = lambda p: sum(int(p[i]) << i for i in range(N)) | sum(int(p[N + i]) << (N + i) for i in range(N))
P = [toint(p) for p in pts]
m = 7
om = lambda a, b: (bin((a & m) & (b >> N)).count('1') + bin((a >> N) & (b & m)).count('1')) & 1
lid = {frozenset(P[i] for i in l): k for k, l in enumerate(L)}
x = [int(t) for t in open(os.path.join(os.path.dirname(C.__file__), 'witness_W5_2.txt'))]
V0 = frozenset(k for k, (l, s) in enumerate(zip(L, S)) if x[l[0]] ^ x[l[1]] ^ x[l[2]] ^ s)
gens = []
for v in range(1, 64):
    t = {a: (a ^ v) if om(a, v) else a for a in range(1, 64)}
    gens.append([lid[frozenset(t[P[i]] for i in l)] for l in L])
seen = {V0}; todo = [V0]
while todo:
    V = todo.pop()
    for g in gens:
        W = frozenset(g[k] for k in V)
        if W not in seen: seen.add(W); todo.append(W)
print('|V| =', len(V0), ' orbit of violated sets under Sp(6,2):', len(seen), ' stabiliser order:', 1451520 // len(seen))
